345	func buildMatchesCondition(call *exprv1.Expr_Call, schema Schema) (Condition, error) {
346		if call.Target == nil {
347			return nil, errors.New("matches requires a target")
348		}
349		targetName, err := getIdentName(call.Target)
350		if err != nil {
351			return nil, err
352		}
353	
354		field, ok := schema.Field(targetName)
355		if !ok {
356			return nil, errors.Errorf("unknown identifier %q", targetName)
357		}
358		if !field.SupportsContains {
359			return nil, errors.Errorf("identifier %q does not support matches()", targetName)
360		}
361		if len(call.Args) != 1 {
362			return nil, errors.New("matches expects exactly one argument")
363		}
364		value, err := getConstValue(call.Args[0])
365		if err != nil {
366			return nil, errors.Wrap(err, "matches only supports literal arguments")
367		}
368		pattern, ok := value.(string)
369		if !ok {
370			return nil, errors.New("matches argument must be a string")
371		}
372		return &RegexCondition{
373			Field:   targetName,
374			Pattern: pattern,
375		}, nil
376	}
