378	func buildValueExpr(expr *exprv1.Expr, pc parseContext) (ValueExpr, error) {
379		if identName, err := getIdentName(expr); err == nil {
380			// `now` is not a schema field; it folds to the frozen evaluation time.
381			if identName == "now" {
382				return &LiteralValue{Value: pc.now.Unix()}, nil
383			}
384			if _, ok := pc.schema.Field(identName); !ok {
385				return nil, errors.Errorf("unknown identifier %q", identName)
386			}
387			return &FieldRef{Name: identName}, nil
388		}
389	
390		if literal, err := getConstValue(expr); err == nil {
391			return &LiteralValue{Value: literal}, nil
392		}
393	
394		if value, ok, err := evaluateNumeric(expr, pc.now); err != nil {
395			return nil, err
396		} else if ok {
397			return &LiteralValue{Value: value}, nil
398		}
399	
400		if boolVal, ok, err := evaluateBoolExpr(expr); err != nil {
401			return nil, err
402		} else if ok {
403			return &LiteralValue{Value: boolVal}, nil
404		}
405	
406		if call := expr.GetCallExpr(); call != nil {
407			if call.Target != nil && isTimestampAccessor(call.Function) {
408				return buildTimestampAccessor(call, pc)
409			}
410			switch call.Function {
411			case "size":
412				if len(call.Args) != 1 {
413					return nil, errors.New("size() expects one argument")
414				}
415				arg, err := buildValueExpr(call.Args[0], pc)
416				if err != nil {
417					return nil, err
418				}
419				return &FunctionValue{
420					Name: "size",
421					Args: []ValueExpr{arg},
422				}, nil
423			case "_+_", "_-_", "_*_":
424				value, ok, err := evaluateNumeric(expr, pc.now)
425				if err != nil {
426					return nil, err
427				}
428				if ok {
429					return &LiteralValue{Value: value}, nil
430				}
431			default:
432				// Fall through to error return below
433			}
434		}
435	
436		return nil, errors.New("unsupported value expression")
437	}
438	
439	func toComparisonOperator(fn string) (ComparisonOperator, error) {
440		switch fn {
441		case "_==_":
442			return CompareEq, nil
443		case "_!=_":
444			return CompareNeq, nil
445		case "_<_":
446			return CompareLt, nil
447		case "_>_":
448			return CompareGt, nil
449		case "_<=_":
450			return CompareLte, nil
451		case "_>=_":
452			return CompareGte, nil
453		default:
454			return "", errors.Errorf("unsupported comparison operator %q", fn)
455		}
456	}
